css:
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=DM+Mono:wght@400;500&display=swap');
* { margin:0; padding:0; box-sizing:border-box; }
body { font-family:'DM Sans',sans-serif; background:#fff; color:#000; font-size:10px; }
.page { padding:12px 16px; }
.header { display:flex; justify-content:space-between; align-items:flex-start; margin-bottom:8px; padding-bottom:6px; border-bottom:2px solid #000; }
.header-left { display:flex; align-items:center; gap:10px; }
.company-logo { max-height:55px; max-width:120px; object-fit:contain; }
.company-name { font-size:15px; font-weight:700; color:#000; }
.tagline { font-size:8px; color:#555; letter-spacing:1.5px; text-transform:uppercase; margin-top:1px; }
.company-contact { text-align:right; font-size:9px; color:#333; line-height:1.7; }
.hero-strip { display:flex; align-items:stretch; margin-bottom:8px; border:1px solid #000; }
.hero-number { background:#fff; padding:8px 14px; display:flex; flex-direction:column; justify-content:center; min-width:130px; border-right:1px solid #000; }
.hero-number .label { font-size:7px; letter-spacing:2px; text-transform:uppercase; color:#666; margin-bottom:2px; }
.hero-number .number { font-family:'DM Mono',monospace; font-size:13px; font-weight:600; color:#000; }
.hero-title { background:#44d8fd; color:#000; padding:8px 20px; display:flex; align-items:center; justify-content:center; flex:1; border-right:1px solid #000; }
.hero-title span { font-size:14px; font-weight:700; letter-spacing:5px; text-transform:uppercase; }
.hero-warranty { background:#fff; padding:8px 14px; display:flex; flex-direction:column; justify-content:center; min-width:140px; }
.hero-warranty .label { font-size:7px; letter-spacing:1.5px; text-transform:uppercase; color:#666; margin-bottom:2px; }
.hero-warranty .value { font-size:10px; font-weight:600; color:#000; }
.info-card-title { font-size:7px; font-weight:700; letter-spacing:2px; text-transform:uppercase; color:#000; background:#44d8fd; padding:3px 8px; }
.info-tbl { width:100%; border-collapse:collapse; }
.info-tbl tr { border-bottom:1px solid #eee; }
.info-tbl tr:last-child { border-bottom:none; }
.info-tbl td { padding:3px 8px; vertical-align:top; }
.info-tbl td.lbl { font-size:8px; font-weight:600; text-transform:uppercase; letter-spacing:0.8px; color:#666; white-space:nowrap; width:75px; padding-top:4px; }
.info-tbl td.val { font-size:10px; font-weight:500; color:#000; }
.section { margin-bottom:8px; }
.section-title { font-size:8px; font-weight:700; letter-spacing:2px; text-transform:uppercase; color:#000; background:#44d8fd; padding:3px 8px; display:inline-block; margin-bottom:4px; }
.modern-table { width:100%; border-collapse:collapse; border:1px solid #000; }
.modern-table thead tr { background:#000; }
.modern-table thead th { padding:5px 8px; font-size:8px; font-weight:600; letter-spacing:1px; text-transform:uppercase; color:#44d8fd; text-align:left; border-right:1px solid #333; }
.modern-table thead th.center { text-align:center; }
.modern-table tbody tr:nth-child(even) { background:#f9f9f9; }
.modern-table tbody td { padding:5px 8px; font-size:10px; color:#000; border-bottom:1px solid #ddd; border-right:1px solid #eee; }
.modern-table tbody td.center { text-align:center; }
.modern-table tbody td.right { text-align:right; font-family:'DM Mono',monospace; }
.check-done { color:#000; font-size:12px; font-weight:700; }
.check-notdone { color:#bbb; font-size:12px; }
.fault-box { border:1px solid #000; padding:6px 10px; min-height:40px; font-size:10px; color:#000; line-height:1.5; border-left:3px solid #44d8fd; background:#fff; }
.billing-row { display:flex; justify-content:flex-end; margin-top:4px; }
.billing-summary { border:1px solid #000; min-width:260px; }
.billing-summary-row { display:flex; justify-content:space-between; padding:4px 12px; border-bottom:1px solid #ddd; font-size:9px; }
.billing-summary-row:last-child { border-bottom:none; background:#44d8fd; padding:6px 12px; }
.bs-label { color:#333; font-weight:500; }
.billing-summary-row:last-child .bs-label { color:#000; font-weight:700; font-size:10px; }
.bs-value { font-family:'DM Mono',monospace; color:#000; font-weight:500; }
.billing-summary-row:last-child .bs-value { color:#000; font-weight:700; font-size:11px; }
.satisfaction { text-align:center; padding:6px; border:1px solid #000; border-left:3px solid #44d8fd; font-size:10px; font-weight:600; color:#000; margin:8px 0; }
.sig-title { font-size:7px; font-weight:700; letter-spacing:1.5px; text-transform:uppercase; color:#000; background:#f5f5f5; padding:4px 8px; border-bottom:1px solid #ddd; }
.sig-image-area { height:55px; text-align:center; vertical-align:middle; border-bottom:1px dashed #ccc; padding:4px 8px; background:#fff; }
.sig-image-area img { max-height:47px; max-width:100%; object-fit:contain; }
.sig-name { font-size:9px; font-weight:700; color:#000; border-top:1px solid #000; padding:3px 8px 2px 8px; }
.sig-email { font-size:8px; color:#555; padding:0 8px 5px 8px; }
.footer { margin-top:8px; padding-top:6px; border-top:2px solid #000; display:flex; justify-content:space-between; align-items:center; }
.footer-note { font-size:8px; color:#666; font-style:italic; }
.ticket-ref { font-size:8px; color:#000; font-family:'DM Mono',monospace; }
